const isNew = $('Crear usuario nuevo (Airtable)').isExecuted;
const trig = $('Normalizar entrada').item.json;
const found = isNew ? ($('Crear usuario nuevo (Airtable)').first().json) : ($('Buscar memoria (Airtable)').first().json);

const session_id = String(trig.message.from.id);
const message_text = trig.message.text;
const user_name = trig.message.from.first_name || 'Expositor';
const record_id = found && found.id ? found.id : null;
const last_summary = isNew ? 'Sin conversaciones previas: es la primera vez que escribe.' : ((found && found['Resumen consolidado']) || 'Sin resumen previo todavía.');
let estadoRaw = found ? found['Estado del caso'] : null;
if (estadoRaw && typeof estadoRaw === 'object') estadoRaw = estadoRaw.name;
const estado_caso = isNew ? 'nuevo' : (estadoRaw || 'nuevo');
let datos_clave = '{}';
try {
  datos_clave = isNew ? '{}' : ((found && found['Datos clave']) || '{}');
  JSON.parse(datos_clave);
} catch(e) { datos_clave = '{}'; }
const prevCount = Number(found ? found['Contador de mensajes'] : 0);
const message_count = (isNew ? 0 : (Number.isFinite(prevCount) ? prevCount : 0)) + 1;

return [{json: { session_id, message_text, user_name, is_new_user: isNew, record_id, last_summary, estado_caso, datos_clave, message_count }}];

