const raw = $json.output ?? {};
const intents = ['consulta','ventas','info_general','desconocida'];
const intent = intents.includes(raw.intent) ? raw.intent : 'desconocida';
let confidence = Number(raw.confidence);
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));
const riskRaw = String(raw.risk || '').toLowerCase();
const risk = ['low','medium','high'].includes(riskRaw) ? riskRaw : 'high';
return [{json: { output: { intent, confidence, risk } }}];

const raw = $json.output ?? {};
let puntos = Array.isArray(raw.puntos_clave) ? raw.puntos_clave.filter(x=>typeof x==='string' && x.trim()).slice(0,5) : [];
if (puntos.length===0) puntos = ['Sin puntos clave registrados.'];
const asunto = (typeof raw.asunto_principal === 'string' && raw.asunto_principal.trim()) ? raw.asunto_principal.trim().slice(0,200) : 'Conversación sin asunto definido.';
const accion = (typeof raw.accion_requerida === 'string' && raw.accion_requerida.trim()) ? raw.accion_requerida.trim().slice(0,200) : 'ninguna';
return [{json: { output: { asunto_principal: asunto, puntos_clave: puntos, accion_requerida: accion } }}];

const j = $json;
// Canal Telegram: pasa tal cual, solo agrega metadatos del canal
if (j.message) {
  return [{json: { ...j, channel: 'telegram', email: '', subject: '', thread_id: '' }}];
}
// Canal Gmail: se transforma al mismo formato que Telegram para reutilizar todo el Manager
const fromRaw = typeof j.From === 'string' ? j.From : String((j.From && j.From.text) || (j.from && j.from.text) || '');
const m = fromRaw.match(/<([^>]+)>/);
const email = (m ? m[1] : fromRaw).trim().toLowerCase();
const nameRaw = fromRaw.replace(/<[^>]*>/, '').replace(/"/g, '').trim();
const subject = String(j.Subject || j.subject || '').trim();
const body = String(j.text || j.textPlain || j.snippet || '').replace(/\s+/g, ' ').trim().slice(0, 4000);
const text = (subject ? subject + ' — ' : '') + body;
return [{json: {
  channel: 'email', email, subject, thread_id: j.threadId || '',
  message: { from: { id: email || 'sin-email', first_name: nameRaw || (email.split('@')[0] || 'Contacto') },
             text, chat: { id: 0 } }   // chat del aprobador humano (HITL por Telegram)
}}];
